typedef struct {
  char str[46];
} str46;
typedef struct {
  char values[2];
} chr2;
typedef struct {
  double values[8];
} dbl8;

__device__ inline bool eq_str46(const char a[46], const char b[46]) {
  int c = 0;
  while (c < 46 && a[c] == b[c]) {
    c++;
  }
  return c == 46;
}

#if CACHE_P_CB != 0
__device__ inline bool eq_str46_2( char const * const a,  char const * const b) {
  int c = 0;
  while (c < 46 && a[c] == b[c]) {
    c++;
  }
  return c == 46;
}
#elif CACHE_L_CB != 0
__device__ inline bool eq_str46_2( char const * const a,  char const * const b) {
  int c = 0;
  while (c < 46 && a[c] == b[c]) {
    c++;
  }
  return c == 46;
}
#else
__device__ inline bool eq_str46_2(char const * const a, char const * const b) {
  int c = 0;
  while (c < 46 && a[c] == b[c]) {
    c++;
  }
  return c == 46;
}
#endif

__device__ inline double calculatePartWeight(const str46 n_input,
                                  const str46 i_input,
                                  const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    } else {
      return (log((1 - pm) / (1 - pu)) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculatePartWeightOnly(const str46 n_input,
                                      const str46 i_input,
                                      const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculatePartWeightFirstname(const str46 n_input,
                                           const str46 i_input,
                                           const char fn_group,
                                           const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (fn_group || eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    } else {
      return (log((1 - pm) / (1 - pu)) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculatePartWeightOnlyFirstname(const str46 n_input,
                                               const str46 i_input,
                                               const char fn_group,
                                               const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (fn_group || eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculatePartWeightBirthname(const str46 n_input,
                                           const str46 i_input,
                                           const str46 i_lastname1, const str46 i_lastname2, const str46 i_lastname3,
                                           const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0 &&
      
      !(eq_str46(i_input.str, i_lastname1.str) ||
        eq_str46(i_input.str, i_lastname2.str) ||
        eq_str46(i_input.str, i_lastname3.str))) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    } else {
      return (log((1 - pm) / (1 - pu)) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculatePartWeightOnlyBirthname(const str46 n_input,
                                               const str46 i_input,
                                               const str46 i_lastname1, const str46 i_lastname2, const str46 i_lastname3,
                                               const double pm, const double puFirst, const double puSecond) {
  
  if (puSecond != 0.0 &&
      
      !(eq_str46(i_input.str, i_lastname1.str) ||
        eq_str46(i_input.str, i_lastname2.str) ||
        eq_str46(i_input.str, i_lastname3.str))) {
    
    double pu = (puFirst < puSecond) ? puFirst : puSecond;

    
    if (eq_str46(n_input.str, i_input.str)) {
      
      return (log(pm / pu) / log(2.0));
    }
  }
  return 0.0;
}

__device__ inline double calculateCryptoPartLastnames(const str46 n_input1, const str46 n_input2, const str46 n_input3,
                                           const str46 i_input1, const str46 i_input2, const str46 i_input3,
                                           const double n_prob1, const double n_prob2, const double n_prob3,
                                           const double i_prob1, const double i_prob2, const double i_prob3,
                                           const double pm) {
  
  double weight = 0.0;

  
  double puFirst = n_prob1;
  double puSecond;

  
  if (puFirst != 0.0) {
    
    puSecond = i_prob1;
    weight += calculatePartWeight(n_input1, i_input1, pm, puFirst, puSecond);

    
    puSecond = i_prob2;
    weight += calculatePartWeightOnly(n_input1, i_input2, pm, puFirst, puSecond);

    
    puSecond = i_prob3;
    weight += calculatePartWeightOnly(n_input1, i_input3, pm, puFirst, puSecond);
  }

  
  puFirst = n_prob2;
  if (puFirst != 0.0) {
    
    puSecond = i_prob2;
    weight += calculatePartWeight(n_input2, i_input2, pm, puFirst, puSecond);

    
    puSecond = i_prob1;
    weight += calculatePartWeightOnly(n_input2, i_input1, pm, puFirst, puSecond);

    
    puSecond = i_prob3;
    weight += calculatePartWeightOnly(n_input2, i_input3, pm, puFirst, puSecond);
  }

  
  puFirst = n_prob3;
  if (puFirst != 0.0) {
    
    puSecond = i_prob3;
    weight += calculatePartWeight(n_input3, i_input3, pm, puFirst, puSecond);

    
    puSecond = i_prob1;
    weight += calculatePartWeightOnly(n_input3, i_input1, pm, puFirst, puSecond);

    
    puSecond = i_prob2;
    weight += calculatePartWeightOnly(n_input3, i_input2, pm, puFirst, puSecond);
  }

  return weight;
}

__device__ inline double calculateCryptoPartFirstnames(const str46 n_input1, const str46 n_input2, const str46 n_input3,
                                            const str46 i_input1, const str46 i_input2, const str46 i_input3,
                                            const double n_prob1, const double n_prob2, const double n_prob3,
