          MATCH_WEIGHT_STR(K1_RES_G_BUFFER(K1_P3_L_TO_G_INDEX_L_1(l_index_l_1), i_wg_r_1, 0, 0));
        #endif
        ID_MEASURE_STR(K1_L_KERNEL_RES(l_index_l_1)) =
        #if L_CB_RES_DEST_LEVEL < LOCAL
          ID_MEASURE_STR(K1_L_REDUCTION_MEM(l_index_l_1, 0));
        #elif L_CB_RES_DEST_LEVEL == LOCAL
          ID_MEASURE_STR(K1_RES_L_BUFFER(l_index_l_1, 0, 0));
        #elif L_CB_RES_DEST_LEVEL == GLOBAL
          ID_MEASURE_STR(K1_RES_G_BUFFER(K1_P3_L_TO_G_INDEX_L_1(l_index_l_1), i_wg_r_1, 0, 0));
        #endif
      }
      #if L_CB_RES_DEST_LEVEL <= LOCAL
      __syncthreads( );
      #elif L_CB_RES_DEST_LEVEL == GLOBAL
      __syncthreads( );
      #endif
      #endif
    }
    #endif
    
    
  
  }
  #endif
}
